{
  "titulo": "Como iniciar um repositório Git e fazer seu primeiro commit",
  "idioma": "pt-BR",
  "descricao": "Siga estes passos para configurar o Git, iniciar um repositório local, criar seu primeiro arquivo, realizar o primeiro commit e, opcionalmente, publicar em um repositório remoto (como o GitHub).",
  "pre_requisitos": [
    "Acesso a um terminal (macOS/Linux: Terminal; Windows: PowerShell ou Terminal)",
    "Git instalado (https://git-scm.com/downloads)",
    "Conta em um provedor de repositórios remotos (opcional), ex.: GitHub, GitLab, Bitbucket"
  ],
  "passos": [
    {
      "etapa": 1,
      "titulo": "Verificar se o Git está instalado",
      "instrucoes": "No terminal, verifique a versão do Git. Se não estiver instalado, baixe e instale a partir do site oficial.",
      "exemplo": "```bash\ngit --version\n```",
      "resultado_esperado": "Exibe algo como: git version 2.x.x"
    },
    {
      "etapa": 2,
      "titulo": "Configurar sua identidade (global)",
      "instrucoes": "Defina seu nome e e-mail para que seus commits fiquem identificados corretamente.",
      "exemplo": "```bash\ngit config --global user.name \"Seu Nome\"\ngit config --global user.email \"seu@email.com\"\n\n# Conferir as configurações salvas\ngit config --global --list\n```",
      "resultado_esperado": "As chaves user.name e user.email aparecem ao listar as configurações."
    },
    {
      "etapa": 3,
      "titulo": "Criar e acessar a pasta do projeto",
      "instrucoes": "Crie um diretório para o projeto e acesse-o.",
      "exemplo": "```bash\nmkdir meu-projeto && cd meu-projeto\n```",
      "resultado_esperado": "Você passa a trabalhar dentro da pasta meu-projeto."
    },
    {
      "etapa": 4,
      "titulo": "Inicializar o repositório Git",
      "instrucoes": "Transforme a pasta atual em um repositório Git.",
      "exemplo": "```bash\ngit init\n```",
      "resultado_esperado": "Uma pasta oculta .git é criada e a mensagem \"Initialized empty Git repository\" é exibida."
    },
    {
      "etapa": 5,
      "titulo": "Criar um arquivo inicial",
      "instrucoes": "Crie um arquivo README.md com um título. Você pode usar seu editor de texto ou o comando abaixo.",
      "exemplo": "```bash\necho \"# Meu Projeto\" > README.md\n```",
      "resultado_esperado": "O arquivo README.md é criado com um título."
    },
    {
      "etapa": 6,
      "titulo": "Verificar alterações e adicionar ao stage",
      "instrucoes": "Veja o status do repositório e adicione o(s) arquivo(s) novo(s) ao stage.",
      "exemplo": "```bash\ngit status\ngit add README.md\n```",
      "resultado_esperado": "git status mostra README.md como \"new file\" pronto para commit."
    },
    {
      "etapa": 7,
      "titulo": "Realizar o primeiro commit",
      "instrucoes": "Confirme as mudanças adicionadas ao stage com uma mensagem clara.",
      "exemplo": "```bash\ngit commit -m \"feat: primeiro commit\"\n```",
      "resultado_esperado": "Um commit é criado e exibido com seu hash e contagem de arquivos alterados."
    },
    {
      "etapa": 8,
      "titulo": "Inspecionar o histórico",
      "instrucoes": "Cheque rapidamente o histórico de commits.",
      "exemplo": "```bash\ngit log --oneline\n```",
      "resultado_esperado": "O commit recém-criado aparece como a entrada mais recente."
    },
    {
      "etapa": 9,
      "titulo": "Conectar a um repositório remoto (opcional)",
      "opcional": true,
      "instrucoes": "Crie um repositório vazio no provedor (ex.: GitHub) e conecte-o como remoto. Em seguida, envie seu branch principal.",
      "exemplo": "```bash\n# Substitua a URL pelo endereço do seu repositório remoto\ngit branch -M main\ngit remote add origin https://github.com/SEU_USUARIO/meu-projeto.git\ngit push -u origin main\n```",
      "resultado_esperado": "O branch main é publicado no repositório remoto e o upstream é configurado."
    },
    {
      "etapa": 10,
      "titulo": "Adicionar um .gitignore (recomendado)",
      "opcional": true,
      "instrucoes": "Crie um arquivo .gitignore para evitar versionar arquivos indesejados. Exemplo de conteúdo:",
      "conteudo_exemplo": "```gitignore\nnode_modules\n.env\n.DS_Store\n```",
      "resultado_esperado": "Arquivos e pastas listados no .gitignore deixam de aparecer como mudanças não rastreadas."
    }
  ],
  "erros_comuns": [
    {
      "problema": "git: command not found (ou comando não reconhecido)",
      "causa": "Git não instalado ou não está no PATH do sistema.",
      "solucao": "Instalar o Git via https://git-scm.com/downloads e reiniciar o terminal."
    },
    {
      "problema": "Nothing to commit, working tree clean",
      "causa": "Nenhum arquivo novo/modificado foi adicionado ao stage.",
      "solucao": "Criar/modificar arquivos e executar `git add <arquivos>` antes do `git commit`."
    },
    {
      "problema": "fatal: not a git repository (or any of the parent directories): .git",
      "causa": "Comandos executados fora de um repositório inicializado.",
      "solucao": "Executar `git init` na pasta correta ou navegar até a pasta do projeto."
    },
    {
      "problema": "Permission denied (publickey) ao fazer push via SSH",
      "causa": "Chave SSH não configurada no provedor remoto.",
      "solucao": "Gerar uma chave (`ssh-keygen`), adicionar a chave pública à sua conta remota, ou usar URL HTTPS do repositório."
    }
    ],
  "proximos_passos": [
    "Criar e alternar branches: `git switch -c minha-feature`",
    "Atualizar seu branch a partir do remoto: `git pull`",
    "Reverter mudanças com segurança: `git restore` e `git revert`",
    "Escrever um README mais completo e adicionar licença (LICENSE)"
  ]
}

